    $title = if ($explicitTitle) { Get-ReplTurnCacheField -Field 'queryTitle' } else { '' }
    try {
        $script:ReplPersistVerbMethod = 'workflow.sessionlog.updateTurn'
        $metaPT = Resolve-ReplPersistPlanTodo -ParamsYaml $ParamsYaml
